function feeModelNote(){return '<div class="mini-note" style="padding:0 2px 15px">Комиссии Limitless: оценка по таблице для каждой цены. Между точками — интерполяция; точная комиссия известна после исполнения.</div>';}
function manualReviewSetting(){return `<label class="check span-full"><input type="checkbox" name="skipManualReview" ${data.state.settings.skipManualReview?'checked':''}>Отключить ручную проверку пар — только виртуальная торговля</label><div class="mini-note span-full">Бот сможет входить в непроверенные пары при доходности выше нуля и не ниже установленного минимального порога. Совпадение исходов не подтверждается: видимый плюс может закончиться убытком при разных правилах выплаты. Остальные проверки и лимиты действуют.</div>`;}
