let executionProfile = null;
function profilePanel(){
 if(source!=='live')return '';
 const p=executionProfile;
 if(!p?.enabled)return '<section class="panel"><h2>Профиль задержек</h2><p>Профилирование выключено.</p></section>';
 const labels={'receipt':'Получение','decode':'Разбор и нормализация','book-update':'Обновление стакана','search':'Поиск возможности','quote':'Стоимость покупки','fees':'Комиссия Limitless','liquidity':'Глубина и стоимость','risk':'Проверки пары и риска','schedule':'Постановка попытки','artificial-delay':'Модельная задержка','recheck':'Повторная проверка','execute':'Виртуальное исполнение','stream-queue':'Очередь потока','decision-queue':'Очередь решения','persistence':'Сохранение','snapshot':'Сбор стаканов','http':'HTTP RTT','snapshot-wait':'После модельного прихода'};
 const ms=v=>v===null?'—':Number(v).toFixed(3);
 Object.assign(labels,{'json-decode':'JSON → объект','quote-to-decision':'Котировка → решение','decision-complete':'Котировка → надёжное сохранение','wal':'Журнал транзакций','checkpoint':'Полный снимок состояния','ui':'Подготовка интерфейса','rate-limit':'Ожидание HTTP-лимитера'});
 const runtime=p.runtime?`<p class="mini-note">Память: ${Number(p.runtime.memoryRssMb).toFixed(1)} МБ · Занятость основного цикла: ${(Number(p.runtime.eventLoopUtilization)*100).toFixed(1)}%${p.runtime.eventLoopDelay?` · Задержка цикла p99: ${ms(p.runtime.eventLoopDelay.p99Ms)} мс (интервал измерения ${p.runtime.eventLoopDelay.resolutionMs} мс)`:''}</p>`:'';
 return `<section class="panel" data-testid="execution-profile"><h2>Профиль задержек</h2><p>Миллисекунды, монотонные часы. Перцентили последних ${p.percentileWindow} вызовов каждого этапа. Вложенные этапы перекрываются: складывать их нельзя. HTTP RTT не равен задержке доставки котировки. Для Limitless JSON декодируется внутри Socket.IO; этап нормализации начинается после него.</p>${runtime}<div class="table-wrap"><table><thead><tr><th>Этап</th><th>Вызовы</th><th>p50</th><th>p95</th><th>p99</th><th>Ошибки/отказы</th><th>HTTP</th></tr></thead><tbody>${p.stages.map(r=>`<tr><td>${esc(labels[r.stage]??r.stage)}</td><td>${r.count}</td><td>${ms(r.p50)}</td><td>${ms(r.p95)}</td><td>${ms(r.p99)}</td><td>${r.rejected}</td><td>${r.networkRequests}</td></tr>`).join('')}</tbody></table></div></section>`;
}
