let source = 'live', page = location.hash.slice(1) in pages ? location.hash.slice(1) : 'overview', data = null, csrf = '', busy = false, polling = false, filter = 'all', search = '', scenario = 'normal', logFilter = '', auditFileNames = [], toastTimer;
const statusTag = status => {const s=statuses[status]??[status,'neutral'];return `<span class="tag ${s[1]}">${esc(s[0])}</span>`;};
function toast(message, error=false){const t=$('#toast');t.textContent=message;t.className=`visible ${error?'error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',6500);}
async function api(route,body){const r=await fetch(route,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'content-type':'application/json','x-local-token':csrf},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.error??`HTTP ${r.status}`);return j;}
let refreshPending=Promise.resolve(),commandPending=Promise.resolve();
async function refresh(force=false){
  if(polling){if(force){await refreshPending;return refresh(true);}return;}
  polling=true;
  refreshPending=(async()=>{
    try{if(page==='logs'&&source==='live'){try{[executionDiagnostics,executionProfile]=await Promise.all([api('/api/diagnostics/execution'),api('/api/diagnostics/profile').catch(()=>null)]);}catch(e){executionDiagnostics={available:false,error:e.message};}}const next=await api(`/api/state?source=${source}${marketParameters()}`);if(next.source!==source)return;data=next;csrf=next.csrf;$('#updated').textContent=`Обновлено ${time(next.at)} · ${source==='live'?'реальные котировки':'синтетический сценарий'}`;if(force||(!['settings','connections'].includes(page)&&!$('#modal').open&&document.activeElement?.tagName!=='INPUT'))render();}
    catch(e){if(force||!data)$('#main').innerHTML=`<div class="banner-error">Не удалось подключиться: ${esc(e.message)}. Проверьте, что локальное приложение запущено.</div>`;}
    finally{polling=false;connectMarketEvents();}
  })();return refreshPending;
}
function command(action,payload){
  const requestedSource=source;
  const execute=async()=>{
    busy=true;document.querySelectorAll('button[data-action]').forEach(b=>b.disabled=true);
    try{const response=await api('/api/command',{source:requestedSource,action,payload});await refresh(true);if(action==='close-all'){const r=response.result;toast(`Закрыто: ${r.closed}. Отменено заявок: ${r.cancelled}. Осталось открытых: ${r.remaining}.${r.remaining?' Нет свежих котировок или достаточной ликвидности — повторите позже.':' Можно менять параметры.'}`,r.remaining>0);}else toast('Готово. Изменение записано в журнал.');}
    catch(e){toast(e.message,true);}
    finally{busy=false;document.querySelectorAll('button[data-action]').forEach(b=>b.disabled=b.dataset.action==='close-all'&&!data.metrics.openTrades);}
  };commandPending=commandPending.then(execute,execute);return commandPending;
}
function heading(title,subtitle,actions=''){return `<section class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions"><select class="source-select" id="source-select" aria-label="Источник данных"><option value="live" ${source==='live'?'selected':''}>Реальные котировки</option><option value="demo" ${source==='demo'?'selected':''}>Демо-сценарии</option></select>${actions}</div></section>`;}
function startButton(){return `<button class="button primary" data-action="${data.state.running?'pause':'start'}" data-testid="trading-toggle">${icon(data.state.running?'pause':'play')}${data.state.running?'Приостановить':'Запустить симуляцию'}</button>`;}
function errorBanner(){const error=data.audit.error||data.state.haltReason;return error?`<div class="banner-error">${esc(error)}</div>`:'';}
function stats(){const m=data.metrics;return `<section class="stats">${[
 ['Капитал счёта',money(m.equity),'wallet',`<span class="tag ${Number(m.totalPnl)>=0?'success':'error'}">${percent(Number(m.totalPnl)/Number(m.initialCapital))}</span><span>от ${money(m.initialCapital)} на старте</span>`],
 ['Реализованный P&L',signed(m.realizedPnl),'arrow',`<span>${m.closedTrades} закрытых сделок</span>`],
 ['Открытые позиции',String(m.openTrades).padStart(2,'0'),'trades',`<span>Зарезервировано ${money(m.reserved)}</span>`],
 ['Комиссии',money(Number(m.cashFees)+Number(m.contractFeesValue)),'settings',`<span>USD + оценка удержанных контрактов</span>`],
 ].map(([label,value,i,bottom],n)=>`<article class="stat-card"><div class="stat-label">${label}${icon(i)}</div><div class="stat-value ${n===1?color(m.realizedPnl):''}" ${n===1?'data-testid="realized-pnl"':''}>${value}</div><div class="stat-bottom">${bottom}</div></article>`).join('')}</section>`;}
function chart(){const points=data.state.equity.slice(-120);const width=700,height=190,padX=10,padY=17;let values=points.map(p=>Number(p.equity));if(!values.length)values=[Number(data.metrics.initialCapital)];let min=Math.min(...values),max=Math.max(...values);if(max-min<.15){min-=.4;max+=.4;}else{const margin=(max-min)*.25;min-=margin;max+=margin;}const x=i=>padX+i*(width-60-padX)/Math.max(1,values.length-1);const y=v=>padY+(max-v)/(max-min)*(height-45);const line=values.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');const area=`${line} L${x(values.length-1)},${height-27} L${padX},${height-27} Z`;return `<div class="panel"><div class="chart-heading"><div><h2>Динамика капитала</h2><div class="chart-value">${money(data.metrics.equity)}<small class="${color(data.metrics.totalPnl)}">${signed(data.metrics.totalPnl)}</small></div></div><span class="tag neutral">Текущая сессия</span></div><div class="chart-wrap"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="График виртуального капитала"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#a8bf87" stop-opacity=".24"/><stop offset="100%" stop-color="#a8bf87" stop-opacity=".02"/></linearGradient></defs>${[0,.33,.66,1].map(f=>{const v=min+(max-min)*f;return `<line x1="${padX}" y1="${y(v)}" x2="${width-50}" y2="${y(v)}" stroke="#edf0e7" stroke-dasharray="3 5"/><text x="${width-43}" y="${y(v)+3}">${v.toFixed(2)}</text>`;}).join('')}<path d="${area}" fill="url(#chart-fill)"/><path d="${line}" fill="none" stroke="#8ea96b" stroke-width="2" stroke-linecap="round"/><circle cx="${x(values.length-1)}" cy="${y(values.at(-1))}" r="3" fill="#799958"/>${points.length?[0,.5,1].map(f=>{const i=Math.floor((points.length-1)*f);return `<text x="${x(i)}" y="${height-5}" text-anchor="${f===0?'start':f===1?'end':'middle'}">${time(points[i].at)}</text>`;}).join(''):''}</svg></div><div class="chart-footer"><span><span class="dot"></span>Ликвидационная оценка по свежим bid</span><span>Нереализованный P&L <strong class="${color(data.metrics.unrealizedPnl)}">${signed(data.metrics.unrealizedPnl)}</strong></span></div></div>`;}
function accounts(){return `<section class="panel accounts"><div class="panel-heading"><h2>Распределение средств</h2><span class="tag neutral">Виртуально</span></div>${[['polymarket','Polymarket','Polygon','P','poly'],['limitless','Limitless','Base','∞','lm'],['bybit','Bybit','Транзитный счёт','BY','bybit']].map(([id,name,network,symbol,cls])=>`<div class="account"><span class="venue-icon ${cls}">${symbol}</span><div class="account-name">${name}<small>${network}</small></div><div class="account-amount">${money(data.state.cash[id])}<small>${money(data.balances[id].available)} \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e</small></div></div>`).join('')}<div class="account-note"><strong>В пути ${money(data.metrics.inTransit)}</strong><br>Заблокировано в позициях ${money(data.metrics.costBasis)}. Все переводы моделируются внутри приложения.</div></section>`;}
function feedStrip(){if(source==='demo')return `<div class="feed-strip demo-banner"><div class="strip-left"><span class="dot"></span><span>Синтетические данные · отдельный виртуальный счёт</span></div><small>Проверка механики, не оценка доходности</small></div>`;const health=data.feed.health,ready=data.feed.ready;return `<div class="feed-strip"><div class="strip-left">${ready?'<span class="dot"></span>':'<span class="spinner"></span>'}<span>${ready?'Поток рыночных данных активен':'Загружаем рынки и стаканы'}<small> · ${data.candidates.length} пар-кандидатов</small></span></div><div class="strip-right"><small>${health?.streams?.polymarket?.connected?'●':'○'} Polymarket</small><small>${health?.streams?.limitless?.connected?'●':'○'} Limitless</small></div></div>${data.feed.observerError?`<div class="banner-error">Сбор данных: ${esc(data.feed.observerError)}</div>`:''}${discoveryNotice()}${health?.ready&&health?.discoveredPairs!=null?'<div class="mini-note" style="padding:0 2px 15px">Каталог может быть просмотрен частично. Совпадение названий требует проверки правил.</div>':''}`;}
function marketTable(){
 const rows=data.candidates.slice(0,10),db=data.marketDatabase;
 return `<section class="panel top-ten" data-testid="market-top-ten"><div class="panel-heading"><h2>Топ‑10 по доходности</h2><span class="tag neutral">${db?'База: '+db.total:'Демо'}</span></div><div class="table-controls"><div class="tabs"><button class="tab ${filter==='all'?'active':''}" data-filter="all">Все пары</button><button class="tab ${filter==='reviewed'?'active':''}" data-filter="reviewed">Проверенные</button><button class="tab ${filter==='watching'?'active':''}" data-filter="watching">В потоке</button><button class="tab ${filter==='strategy'?'active':''}" data-filter="strategy">По стратегии</button></div><input class="search" id="market-search" placeholder="Поиск по всей базе…" aria-label="Поиск рынка" value="${esc(search)}"></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>РЫНОК / СОБЫТИЕ</th><th>ДО ЗАВЕРШЕНИЯ</th><th>ДОХОДНОСТЬ ПОСЛЕ РАСХОДОВ</th><th>УСЛОВИЯ ВХОДА</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr data-market-row><td><div class="market-title" title="${esc(p.title)}">${esc(p.title)}</div><div class="market-sub">Limitless: ${esc(p.limitlessTitle)}</div><div class="quote-age">Свежая оценка · ${time(p.updatedAt??data.at)}</div></td><td>${date(p.endsAt)}</td><td><span class="numeric ${color(p.profit)}">${p.roi==null?'—':percent(p.roi)}</span><div class="market-sub">${p.profit==null?'Нет оценки':signed(p.profit)+' / '+data.state.settings.targetNetShares+' контрактов'}</div></td><td>${reviewBadge(p)}${pairBlocker(p)}</td><td><button class="button small" data-pair="${esc(p.id)}">Правила ↗</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>${source==='demo'?'Запустите демо-сценарий':'Свежие оценки по фильтру пока отсутствуют'}</strong><p>База продолжает обновляться на сервере. Устаревшие котировки не участвуют в текущем рейтинге.</p></div>`}<div class="table-bottom"><span>Показано ${rows.length}, максимум 10 · сортировка по текущему ROI</span><span>Поиск и фильтры работают по всей базе</span></div></section>`;
}
function activity(){const events=data.state.events.slice(-5).reverse();return `<section class="panel"><div class="panel-heading"><h2>Последние события</h2><a href="#logs" class="activity-heading-link">Журнал ↗</a></div>${events.length?`<div class="activity">${events.map(e=>`<div class="activity-item ${/reject|error|halt/.test(e.type)?'error':''}"><span class="activity-mark">${/fill|settle/.test(e.type)?'✓':/reject|error/.test(e.type)?'!':'↗'}</span><div><p>${esc(e.message)}</p><small>${time(e.at)} · ${esc(e.type)}</small></div></div>`).join('')}</div>`:'<div class="empty"><div class="empty-icon">◷</div><strong>История появится здесь</strong><p>Запустите виртуальную торговлю или демонстрационный сценарий.</p></div>'}<div class="mini-note">Каждая операция связана с заявкой и исходным стаканом в диагностическом журнале.</div></section>`;}
function scenarioPanel(){const scenarios=[['normal','Полный цикл','Покупка → ожидание → выплата'],['partial','Частичный fill','Неполное покрытие и выход'],['rejection','Отказ второй стороны','Аварийная продажа остатка'],['delayed','Задержка расчёта','Капитал остаётся занят'],['mismatch','Разные результаты','Обе позиции могут проиграть']];return `<div class="scenario-grid">${scenarios.map(([id,title,desc],i)=>`<button class="scenario-card ${scenario===id?'selected':''}" data-scenario="${id}"><span class="scenario-number">СЦЕНАРИЙ 0${i+1}</span><strong>${title}</strong><small>${desc}</small></button>`).join('')}</div><div class="scenario-controls"><button class="button primary" data-action="demo" data-testid="run-demo">${icon('play')}Запустить сценарий</button><p>Ускоренный тест: 16 секунд, задержанный расчёт — 45 секунд. Результаты изолированы от реальных котировок.</p></div>`;}
