function tradeRows(){const trades=sortedTrades();return `<section class="panel"><div class="panel-heading"><h2>История виртуальных сделок</h2><span class="tag neutral">${trades.length} сделок</span></div>${trades.length?`<div class="table-scroll"><table><thead><tr>${tradeSortHeader('title','СОБЫТИЕ')}${tradeSortHeader('status','СТАТУС')}${tradeSortHeader('cost','РАСХОД')}${tradeSortHeader('proceeds','ПОСТУПЛЕНИЯ')}${tradeSortHeader('expectedRoi','СПРЕД ПРИ СИГНАЛЕ')}${tradeSortHeader('realizedPnl','РЕАЛИЗОВАННЫЙ P&L')}${tradeSortHeader('signalAt','ВРЕМЯ ВХОДА')}<th></th></tr></thead><tbody>${trades.map(t=>`<tr><td><div class="market-title">${esc(t.title)}</div><div class="market-sub">${date(t.signalAt)} · спред при сигнале: ${percent(t.expectedRoi)} · ${t.id.slice(0,8)} · ${t.source==='demo'?'синтетический тест':'реальные котировки'}</div></td><td>${statusTag(t.status)}${t.identityWarning?'<div class="market-sub">Ошибка прежнего сопоставления: разные рынки</div>':''}</td><td class="numeric">${money(t.orders.reduce((s,o)=>s+Number(o.cost),0))}</td><td class="numeric">${money(t.orders.reduce((s,o)=>s+Number(o.proceeds),0))}</td><td class="numeric">${percent(t.expectedRoi)}</td><td class="numeric ${color(t.realizedPnl)}">${signed(t.realizedPnl)}</td><td class="nowrap">${date(t.signalAt)}</td><td><button class="button small" data-trade="${t.id}">Детали ↗</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">⇄</div><strong>Пока нет виртуальных сделок</strong><p>На реальном рынке нужны проверенная пара, положительный спред после расходов и доступный виртуальный баланс. Демо позволяет проверить механику сразу.</p><button class="button" data-action="switch-demo">Открыть демо-сценарии ↗</button></div>`}</section>`;}
function transfers(){return `<section class="panel mt"><div class="panel-heading"><h2>Балансировка через Bybit</h2><button class="button small" data-action="rebalance">Виртуально выровнять балансы</button></div>${data.state.transfers.length?`<div class="table-scroll"><table><thead><tr><th>МАРШРУТ</th><th>СУММА</th><th>КОМИССИЯ</th><th>СОСТОЯНИЕ</th></tr></thead><tbody>${[...data.state.transfers].reverse().map(t=>`<tr><td>${esc(t.from)} → Bybit → ${esc(t.to)}</td><td>${money(t.amount)}</td><td>${money(t.fee)}</td><td><span class="tag ${t.status==='COMPLETED'?'success':'warning'}">${t.status==='COMPLETED'?'Завершён':t.status==='DEPOSIT_PENDING'?'Ждём депозит':'Ждём вывод'}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="mini-note">Проверяем депозиты, задержку и вывод в модели. Подключение к аккаунту Bybit отсутствует.</div>'}</section>`;}
