const fields=[['initialPerVenue','Баланс на каждой площадке, $','100','Новый капитал применяется в пустой сессии.'],['targetNetShares','Чистых контрактов на сторону','10','После удержания комиссии в контрактах.'],['maxPositionCost','Общий бюджет сделки, $','10','Обе стороны вместе.'],['minRoi','Минимальная доходность, доля','0.03','0,03 означает 3%.'],['maxPositions','Одновременных сделок','2','Очередь и ожидание расчёта занимают слот.'],['cashReserve','Резерв на площадке, $','5','Не расходуется на новые покупки.'],['latencyMs','Задержка заявки, мс','400','Исполнение по следующему свежему снимку.'],['maxSlippage','Допуск цены, доля','0.005','0,005 означает до 0,5% ухудшения общей стоимости покупки пары. Все проверки прибыли и риска сохраняются.'],['lossLimit','Лимит реализованного убытка, $','10','Новые входы останавливаются.'],['rejectProbability','Вероятность отказа, доля','0.01','Допущение модели, не измеренная статистика.'],['partialProbability','Вероятность частичного fill, доля','0.03','Половина заявки в тесте частичного исполнения.'],['seed','Seed сценариев исполнения','42317','Повторяемая последовательность случайных событий.'],['rebalanceThreshold','Порог балансировки, $','15','Запуск при низком свободном балансе.'],['rebalanceFee','Комиссия перевода в модели, $','0.25','Не является тарифом Bybit.'],['transferDelayMs','Задержка каждого этапа перевода, мс','3000','Депозит и вывод моделируются отдельно.']];
