document.addEventListener('click',e=>{
  const button=e.target.closest('[data-strategy-profile]');if(!button)return;
  const profile=data.strategyProfiles?.[button.dataset.strategyProfile];if(!profile)return;
  for(const [key,value] of Object.entries(profile)){
    const input=document.querySelector(`#settings-form [name="${key}"]`);if(!input)continue;
    if(input.type==='checkbox')input.checked=value;else input.value=value;
  }
  toast('Профиль подставлен в форму. Проверьте параметры и сохраните.');
});
function connectionsPage(){return heading('Подключения','Поля подготовлены для будущего этапа интеграции.')+`<div class="callout">Сейчас используются только публичные рыночные данные. <strong>Поля ниже — макеты:</strong> значения не отправляются на сервер, не сохраняются и не используются для торговли. Настоящие ключи сейчас не нужны.</div><div class="connection-grid">${[
 ['poly','P','Polymarket','Polygon / CLOB',['API Key','API Secret','Passphrase','Адрес рабочего кошелька']],['lm','∞','Limitless','Base / CLOB',['API Token ID','API Token Secret','Адрес рабочего кошелька']],['bybit','BY','Bybit','Перераспределение ликвидности',['API Key','API Secret','Адрес депозита Polygon','Адрес вывода Base']],['other','↗','Blockchain RPC','Polygon / Base',['Polygon RPC URL','Base RPC URL']],
 ].map(([cls,symbol,name,sub,inputs])=>`<form class="panel connection-card" data-connection="${name}" autocomplete="off"><div class="connection-card-head"><span class="venue-icon ${cls}">${symbol}</span><div><h2>${name}</h2><p class="subtitle" style="margin-top:4px">${sub}</p></div><span class="tag neutral">Заглушка</span></div>${inputs.map(label=>`<label class="field">${label}<input type="${/Secret|Key|Passphrase/.test(label)?'password':'text'}" placeholder="Здесь будет ${label}" autocomplete="off" data-placeholder-field></label>`).join('')}<button class="button" type="submit">Проверить макет</button><p>Реальное подключение отключено в этой версии. Виртуальная торговля работает без этих данных.</p></form>`).join('')}</div>`;}
function tradingLogsPage(){
  const entries=data.recentLogs.filter(e=>!logFilter||`${e.category} ${JSON.stringify(e.payload)}`.toLowerCase().includes(logFilter.toLowerCase())).reverse();
  return heading('Журнал сделок','Заявки, исполнения, комиссии, закрытия и результаты виртуальной торговли.',`<a class="button" href="/api/export?source=${source}">${icon('download')}Выгрузить сессию</a>`)+
  `<section class="panel"><div class="panel-heading"><h2>События торговли</h2><span class="tag ${data.audit.error?'error':'success'}">${data.audit.error?'Запись остановлена':'Только торговые события'}</span></div>
  <div class="log-summary"><span>Архив <strong>${(data.audit.bytes/1024/1024).toFixed(1)} МБ</strong> / ${(data.audit.limitBytes/1024/1024).toFixed(0)} МБ</span><span>Записей за запуск <strong>${data.audit.records.toLocaleString('ru-RU')}</strong></span><span>В очереди <strong>${(data.audit.queuedBytes/1024).toFixed(0)} КБ</strong></span></div>
  <div class="log-tools"><input class="search" id="log-search" value="${esc(logFilter)}" placeholder="Поиск по событиям…" aria-label="Поиск по журналу"><span class="tag neutral">Последние 100 торговых событий</span></div>
  <div class="log-list">${entries.length?entries.slice(0,100).map(e=>`<div class="log-row"><time>${time(e.at)}</time><span class="tag ${/error|reject|halt/.test(e.category)?'error':'neutral'}">${esc(e.category)}</span><span class="log-message">${esc(e.payload?.message??e.payload?.error??'Подробности торговой операции')}</span><button data-log="${e.id}" aria-label="Открыть запись">↗</button></div>`).join(''):'<div class="empty"><strong>По этому фильтру событий нет</strong></div>'}</div></section>
  <section class="panel mt"><div class="panel-heading"><h2>Архивы торговых событий</h2><button class="button small" data-action="load-files">Показать файлы</button></div>
  <div class="mini-note">Gzip JSONL: заявки, причины отказов и закрытий, стаканы при исполнении, комиссии, расчёты и результаты сделок. Также сохраняются настройки и критические ошибки. Поток котировок и периодические снимки капитала в журнал не записываются. Ключи и секреты не записываются. При достижении лимита запись и торговля останавливаются.</div>
  <div id="audit-files" class="file-list">${auditFileNames.map(name=>`<a class="file-link" href="/api/logs/download?name=${encodeURIComponent(name)}"><span>${esc(name)}</span><span>Скачать ↓</span></a>`).join('')}</div></section>`;
}
function render(){if(!data)return;$('#breadcrumb').textContent=pages[page];$('#navigation').innerHTML=Object.entries(pages).map(([id,title])=>`<a href="#${id}" aria-label="${title}" title="${title}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${title}</span>${id==='markets'?`<span class="nav-count">${data.feed.coverage?.total??data.candidates.length}</span>`:''}</a>`).join('');$('#main').innerHTML=page==='overview'?overview():page==='markets'?heading('Рынки и пары','Сравнивайте условия расчёта, а затем разрешайте виртуальные входы.',startButton())+errorBanner()+feedStrip()+liveDatabasePanel()+tradingStatus()+marketTable()+coveragePanel(false)+feeModelNote()+manualReviewBanner()+additionalSourcesPanel():page==='trades'?tradesPage():page==='settings'?settingsPage():page==='connections'?connectionsPage():logsPage();}
function showModal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть">×</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function plain(html){return new DOMParser().parseFromString(html,'text/html').body.textContent??'';}
async function openPair(id){try{if(source==='demo'){toast('Эта пара синтетическая и используется только для проверки механики.');return;}const p=await api(`/api/pair?id=${encodeURIComponent(id)}`);showModal('Проверка правил пары',`<div class="callout">Разрешение относится только к виртуальным сделкам. Сравните условия полностью: похожее название не гарантирует одинаковую выплату.</div><div class="rules-grid">${[['Polymarket',p.polymarket],['Limitless',p.limitless]].map(([name,m])=>`<div class="rule-box"><h3>${name}</h3><strong>${esc(m.title)}</strong><p>${esc(plain(m.description))}</p><p>Завершение: ${date(m.endsAt)}</p><small>Источник: ${esc(m.resolutionSource)}<br><br>Хеш: ${esc(m.rulesHash)}</small></div>`).join('')}</div><form id="review-form" data-pair-id="${esc(id)}"><div class="checks">${['YES / Up на обеих площадках означает одно условие','Источник данных и версия оракула совпадают','Период наблюдения, время и часовой пояс совпадают','Порог и правило равенства порогу совпадают','Правила отмены, переноса и резервного расчёта совместимы'].map(t=>`<label class="check"><input type="checkbox" name="review-check" required>${t}</label>`).join('')}</div><label class="field">Обоснование совместимости<textarea name="notes" rows="3" minlength="20" maxlength="4000" required placeholder="Почему выплаты этой пары действительно дополняют друг друга?"></textarea></label><button class="button primary" type="submit">Разрешить для виртуальной торговли</button></form>`);}catch(e){toast(e.message,true);}}
function openTrade(id){const t=data.state.trades.find(t=>t.id===id);if(!t)return;const events=data.state.events.filter(e=>e.tradeId===id);showModal('Детали виртуальной сделки',`<div class="details-grid"><div class="detail-item"><small>Событие</small>${esc(t.title)}</div><div class="detail-item"><small>Статус</small>${statusTag(t.status)}</div><div class="detail-item"><small>ID / источник</small>${t.id}<br>${t.source==='demo'?'Синтетический сценарий':'Реальные котировки'}</div><div class="detail-item"><small>Реализованный результат</small><strong class="${color(t.realizedPnl)}">${signed(t.realizedPnl)}</strong></div></div>${executionDetails(t)}<div class="rules-grid mt">${t.orders.map(o=>`<div class="rule-box"><h3>${o.venue} · ${o.outcome.toUpperCase()}</h3><p>Состояние: ${o.status}\nВаловых контрактов: ${o.grossShares}\nЧистых контрактов: ${o.netShares}\nОсталось: ${o.heldShares}\nРасход: ${money(o.cost)}\nПоступления: ${money(o.proceeds)}\nКомиссия USD: ${o.cashFee}\nКомиссия в контрактах: ${o.contractFee}\nРезультат площадки: ${o.payoutPerShare??'ожидается'}${o.error?'\nПричина: '+o.error:''}</p></div>`).join('')}</div>${['SCHEDULED','OPEN','UNHEDGED','WAITING_RESOLUTION'].includes(t.status)?`<div class="button-row mt"><button class="button danger" data-close-trade="${id}">Виртуально закрыть по доступным bid</button></div>`:''}<h3 class="mt">События сделки</h3><pre class="json-view">${esc(JSON.stringify(events,null,2))}</pre>`);}
document.addEventListener('click',async e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.tradeSort){const key=target.dataset.tradeSort;tradeSort={key,direction:tradeSort.key===key&&tradeSort.direction==='desc'?'asc':'desc'};render();return;}if(target.dataset.filter){filter=target.dataset.filter;await refresh(true);}if(target.dataset.scenario){scenario=target.dataset.scenario;render();}if(target.dataset.pair)await openPair(target.dataset.pair);if(target.dataset.trade)openTrade(target.dataset.trade);if(target.dataset.closeTrade){$('#modal').close();await command('close',{tradeId:target.dataset.closeTrade});}if(target.dataset.log){const entry=data.recentLogs.find(e=>e.id===target.dataset.log);showModal('Полная запись события',`<pre class="json-view">${esc(JSON.stringify(entry,null,2))}</pre>`);}const action=target.dataset.action;if(!action)return;if(action==='close-modal'){$('#modal').close();return;}if(action==='switch-demo'){source='demo';page='overview';location.hash='overview';await refresh(true);return;}if(action==='load-files'){try{const j=await api('/api/logs/files');auditFileNames=j.files;$('#audit-files').innerHTML=j.files.length?j.files.map(name=>`<a class="file-link" href="/api/logs/download?name=${encodeURIComponent(name)}"><span>${esc(name)}</span><span>Скачать ↓</span></a>`).join(''):'<span class="muted">Архив пока пуст</span>';}catch(e){toast(e.message,true);}return;}if(action==='rescan'){try{await api('/api/rescan',{});toast('Обновление каталога запрошено.');}catch(e){toast(e.message,true);}return;}if(action==='reset'){showModal('Новая виртуальная сессия',`<p>Текущая сессия будет сохранена в архиве. Балансы нового счёта начнутся с ${money(data.state.settings.initialPerVenue)} на каждой площадке.</p><button class="button primary" data-action="confirm-reset">Создать новую сессию</button>`);return;}if(action==='confirm-reset'){$('#modal').close();await command('reset');return;}await command(action,action==='demo'?{scenario}:undefined);});
document.addEventListener('change',async e=>{if(e.target.id==='skip-review-toggle'){await command('review-mode',{enabled:e.target.checked});}if(e.target.id==='source-select'){source=e.target.value;filter='all';search='';await refresh(true);}});
document.addEventListener('input',e=>{if(e.target.id==='market-search'){search=e.target.value;clearTimeout(searchDelay);searchDelay=setTimeout(()=>void refresh(true),250);}if(e.target.id==='log-search'){const start=e.target.selectionStart;logFilter=e.target.value;render();const field=$('#log-search');field?.focus();field?.setSelectionRange(start,start);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.dataset.connection){form.reset();toast('Макет проверен. Значения очищены и никуда не отправлены. Реальное подключение отключено.');return;}if(form.id==='settings-form'){const fd=new FormData(form);const settings={};for(const [key]of fields)settings[key]=['initialPerVenue','targetNetShares','maxPositionCost','cashReserve','lossLimit','rebalanceThreshold','rebalanceFee','minProfitUsd','maxUnhedgedLossUsd','maxTotalExposureUsd'].includes(key)?String(fd.get(key)):Number(fd.get(key));settings.autoRebalance=fd.has('autoRebalance');settings.skipManualReview=fd.has('skipManualReview');await command('settings',settings);}if(form.id==='review-form'){try{const checks=[...form.querySelectorAll('[name="review-check"]')].map(c=>c.checked);await api('/api/review',{pairId:form.dataset.pairId,notes:new FormData(form).get('notes'),checks});$('#modal').close();await refresh(true);toast('Проверка сохранена. Каталог обновляется.');}catch(e){toast(e.message,true);}}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1) in pages?location.hash.slice(1):'overview';filter='all';search='';render();void refresh(true);window.scrollTo(0,0);});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
await refresh(true);setInterval(()=>void refresh(),2000);

function pairBlocker(pair){
  if(!pair.review.approved&&!data.state.settings.skipManualReview&&!(pair.entryReasons??[]).length)return '';
  let label='';
  if(pair.profit!==null&&Number(pair.profit)<=0)label='Вход в убыток';
  else if(pair.roi!==null&&Number(pair.roi)<data.state.settings.minRoi)label=`Ниже порога ${percent(data.state.settings.minRoi)}`;
  else if((pair.entryReasons??pair.reasons).length){const blocked=pair.entryReasons??pair.reasons;label=reasons[blocked[0]]??blocked[0];}
  return label?`<div class="market-sub" title="${esc((pair.entryReasons??pair.reasons).map(r=>reasons[r]??r).join('; '))}">${esc(label)}</div>`:'';
}
function tradingStatus(){
 if(source==='live'&&data.marketDatabase){const d=data.marketDatabase;return `<div class="callout" data-testid="trading-status"><strong>${data.state.running?'Виртуальные входы включены':'Входы на паузе, котировки собираются'}</strong><br>Свежих положительных оценок: ${d.positive}. По выбранному сроку удержания подходят ${d.eligible} из ${d.total} пар. Совпали проверки при последнем расчёте: ${d.ready}. ${data.state.running?'Вход создаётся только при прохождении проверок обеих сторон.':'Для начала виртуальных входов нажмите «Запустить симуляцию».'}</div>`;}

  if(source!=='live'||!data.state.running||data.state.haltReason||data.audit.error)return '';
  const reviewed=data.candidates.filter(p=>(p.review.approved||data.state.settings.skipManualReview)&&p.watched&&Date.parse(p.endsAt)>data.at);
  const ready=reviewed.filter(p=>!(p.entryReasons??[]).length&&p.evaluations.some(e=>e.status==='research-positive'));
  const best=reviewed.filter(p=>p.roi!==null).sort((a,b)=>Number(b.roi)-Number(a.roi))[0];
  let title='Торговля запущена · ожидаем подходящую возможность';
  let message=`${data.state.settings.skipManualReview?'Пар для тестовых входов':'Проверенных пар в потоке'}: ${reviewed.length}. Для входа требуется доходность от ${percent(data.state.settings.minRoi)} после расходов и прохождение всех проверок.`;
  if(!data.feed.ready)message='Ожидаем загрузку рынков и свежие стаканы. До этого новые заявки не создаются.';
  else if(!reviewed.length)message='Среди текущих пар в потоке нет проверенных. Откройте правила подходящей пары и проверьте условия расчёта.';
  else if(ready.length){title='Торговля запущена · проверяем условия исполнения';message=`Пар с подходящей оценкой: ${ready.length}. Также учитываются свободный баланс, лимит позиций, резерв заявки и предыдущий вход в это событие.`;}
  else if(best)message+=` Лучшая текущая оценка среди них: ${percent(best.roi)} (${signed(best.profit)} на ${data.state.settings.targetNetShares} чистых контрактов). Подтверждение правил само по себе не делает сделку прибыльной.`;
  return `<div class="callout" data-testid="trading-status"><strong>${title}</strong><br>${esc(message)}</div>`;
}

function marketParameters(){return filter==='all'&&!search?'':`&filter=${encodeURIComponent(filter)}&search=${encodeURIComponent(search)}`;}
function liveDatabasePanel(){
 if(source!=='live'||!data.marketDatabase)return '';const d=data.marketDatabase;
 return `<div class="live-db" data-testid="live-database"><span class="dot"></span><strong>База обновляется в реальном времени</strong><span>${d.total} пар · ${d.freshCalculated} свежих оценок · ${d.positive} положительных</span><span class="db-details">Обновление: <time>${d.updatedAt?time(d.updatedAt):'ожидаем первые стаканы'}</time> · На странице только топ‑10 · Сохранение: SQLite${d.error?' · Ошибка записи: '+esc(d.error):''}</span>${!d.freshCalculated&&d.calculated?`<span class="db-details">${d.calculated} рассчитанных оценок исключены из рейтинга: не пройдены проверки актуальности или согласованности стаканов. Ожидаем свежие данные обеих площадок.</span>`:''}</div>`;
}
function connectMarketEvents(){
 const key=source==='live'?marketParameters():'';
 if(source!=='live'){marketEvents?.close();marketEvents=null;marketEventsKey='';return;}
 if(marketEvents&&marketEventsKey===key&&marketEvents.readyState!==EventSource.CLOSED)return;
 marketEvents?.close();marketEventsKey=key;const stream=new EventSource('/api/markets/stream?source=live'+key);marketEvents=stream;
 stream.onmessage=event=>{if(stream!==marketEvents||source!=='live'||!data)return;const next=JSON.parse(event.data);data.candidates=next.candidates;data.marketDatabase=next.database;
 if(data.feed.coverage){data.feed.coverage.calculated=next.database.calculated;data.feed.coverage.freshCalculated=next.database.freshCalculated;}
 if(['overview','markets'].includes(page)&&!$('#modal').open&&document.activeElement?.tagName!=='INPUT')render();};
}
